package com.smartmanager.nativeapp;
import android.content.*;import android.util.Base64;import java.nio.charset.StandardCharsets;import java.util.*;
/** Multiple non-secret templates; legacy preferences remain compatible. */
public final class TemplateStore {private final SharedPreferences p;public TemplateStore(Context c){p=c.getSharedPreferences("card_templates",Context.MODE_PRIVATE);}public synchronized List<CardTemplate> all(){ArrayList<CardTemplate>o=new ArrayList<>();for(String l:p.getString("archive","").split("\\n"))try{String[]x=l.split("\\|",-1);if(x.length==13)o.add(new CardTemplate(x[0],dec(x[1]),dec(x[2]),Integer.parseInt(x[3]),Integer.parseInt(x[4]),Integer.parseInt(x[5]),Integer.parseInt(x[6]),Integer.parseInt(x[7]),Integer.parseInt(x[8]),"1".equals(x[9]),"1".equals(x[10]),"1".equals(x[11]),"1".equals(x[12])));}catch(Exception ignored){}if(o.isEmpty())o.add(new CardTemplate("default",p.getString("name","Smart Manager A4"),p.getInt("w",595),p.getInt("h",842),p.getInt("rows",6),p.getInt("columns",2),p.getInt("margin",26),p.getInt("gap",9),true,true,true,true));return o;}public boolean select(String id){for(CardTemplate t:all())if(t.id.equals(id))return p.edit().putString("selected",id).commit();return false;}public boolean remove(String id){if("default".equals(id))return false;return p.edit().putString("selected","default").commit();}public CardTemplate get(){String id=p.getString("selected","default");for(CardTemplate t:all())if(t.id.equals(id))return t;return all().get(0);}public boolean save(CardTemplate t){ArrayList<CardTemplate>a=new ArrayList<>(all());boolean f=false;for(int i=0;i<a.size();i++)if(a.get(i).id.equals(t.id)){a.set(i,t);f=true;}if(!f)a.add(t);StringBuilder b=new StringBuilder();for(CardTemplate x:a)b.append(x.id).append('|').append(enc(x.name)).append('|').append(enc(x.imageUri)).append('|').append(x.paperW).append('|').append(x.paperH).append('|').append(x.rows).append('|').append(x.columns).append('|').append(x.margin).append('|').append(x.gap).append('|').append(x.showUser?1:0).append('|').append(x.showPassword?1:0).append('|').append(x.showProfile?1:0).append('|').append(x.showSerial?1:0).append('\n');return p.edit().putString("archive",b.toString()).putString("selected",t.id).commit();}private static String enc(String s){return Base64.encodeToString(s.getBytes(StandardCharsets.UTF_8),2);}private static String dec(String s){return new String(Base64.decode(s,2),StandardCharsets.UTF_8);}}
